package com.tenora365.controller;import com.tenora365.tenant.TenantContext;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.nio.file.*;import java.util.*;
@RestController @RequestMapping("/api/files") public class FileController{@Value("${app.storage-dir}")String root;@PostMapping("/upload")Map<String,Object> upload(@RequestParam MultipartFile file)throws Exception{if(file.isEmpty())throw new IllegalArgumentException("Empty file");if(file.getSize()>10*1024*1024)throw new IllegalArgumentException("Max 10MB");String n=file.getOriginalFilename()==null?"file":file.getOriginalFilename();String ext=n.contains(".")?n.substring(n.lastIndexOf('.')+1).toLowerCase():"";if(Set.of("exe","js","sh","bat","cmd").contains(ext))throw new IllegalArgumentException("File type not allowed");Path dir=Path.of(root,String.valueOf(TenantContext.get()));Files.createDirectories(dir);String key=UUID.randomUUID()+"."+ext;Files.copy(file.getInputStream(),dir.resolve(key),StandardCopyOption.REPLACE_EXISTING);return Map.of("key",key,"name",n,"size",file.getSize());}}
